mapper.select:
SELECT * FROM fund_nav_history WHERE fund_code=#{fundCode}
AND nav_date >= #{startDate}
ORDER BY nav_date ASC

SELECT * FROM fund_period_performance
WHERE fund_code=#{fundCode}
  AND as_of = (
      SELECT MAX(latest.as_of)
      FROM fund_period_performance latest
      WHERE latest.fund_code=#{fundCode}
  )
ORDER BY FIELD(period, '1m', '3m', '6m', '1y', '3y')

SELECT * FROM market_detail_slice_state
WHERE fund_code=#{fundCode} AND slice_type=#{sliceType}
FOR UPDATE

SELECT * FROM stock_price_bar WHERE stock_code=#{stockCode} AND market=#{market} AND granularity=#{granularity}
AND bar_time >= #{startTime}
ORDER BY bar_time ASC
